INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63309, 'spa', 'Suficiente, bastante', 'Denota lo que es bastante o adecuado para su propósito. Mateo 6:34 enseña que a cada día le basta (ἀρκετὸν) su propio mal, sin necesidad de sumar la preocupación del mañana. Mateo 10:25 afirma que le basta (ἀρκετὸν) al discípulo ser como su maestro. Primera de Pedro 4:3 declara que el tiempo pasado fue suficiente (ἀρκετὸς) para entregarse a los deseos de la carne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63310, 'spa', 'Ser suficiente, bastar', 'Ser suficiente, bastar: se usa de cosas, provisiones o recursos que satisfacen una necesidad o cumplen un requisito. Felipe calcula que doscientos denarios de pan no ''bastarian'' para la multitud (Jn 6:7), a las virgenes insensatas se les dice que quiza no haya suficiente aceite para todas (Mt 25:9), y Jesus responde a la peticion de Felipe de ver al Padre con ''eso no te basta?'' (Jn 14:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63312, 'spa', 'Estar contento, satisfecho', 'Estar contento, estar satisfecho con las propias circunstancias: formas en voz media/pasiva que expresan una disposicion interior de satisfaccion mas que cantidad objetiva. Juan el Bautista ordena a los soldados que se ''contenten'' con su paga (Lc 3:14), Pablo ensena que el alimento y el vestido deben bastarnos (1 Ti 6:8), Hebreos exhorta al contentamiento libre del amor al dinero (He 13:5), y Diotrefes no se ''contenta'' con la autoridad que ya tiene (3 Jn 1:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63318, 'spa', 'Carro o carroza', 'Vehículo con ruedas tirado por caballos, que abarca tanto el carruaje de viaje (como en Hechos 8:28-29, 38, donde el eunuco etíope lee las Escrituras camino a Gaza) como el carro de guerra evocado en la imaginería apocalíptica (Apocalipsis 9:9, donde el estruendo de las langostas demoníacas se asemeja al fragor de carros lanzándose a la batalla).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63322, 'spa', 'negar, desconocer', 'negar, desconocer');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63327, 'spa', 'rehusar, rechazar', 'rehusar, rechazar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63329, 'spa', 'renunciar, negarse a sí mismo', 'renunciar, negarse a sí mismo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63345, 'spa', 'el Cordero (título cristológico)', 'el Cordero (título cristológico)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63347, 'spa', 'corderitos (sentido literal)', 'corderitos (sentido literal)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63349, 'spa', 'Arar, labrar', 'Se usa literalmente del trabajo agrícola de arar, pero aplicado a principios espirituales. Lucas 17:7 plantea una pregunta sobre un siervo que está arando (ἀροτριῶντα) o pastoreando, ilustrando el servicio fiel sin recompensa inmediata. Primera de Corintios 9:10 lo aplica dos veces: el que ara (ἀροτριῶν) debe arar con esperanza, pues los que realizan labor espiritual merecen sustento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63351, 'spa', 'Rapiña y codicia', 'Denota tanto el acto de despojar como el espíritu codicioso que lo impulsa. Mateo 23:25 y Lucas 11:39 condenan a los líderes religiosos por su «codicia» (ἁρπαγῆς) interior pese a su limpieza exterior. Hebreos 10:34 celebra la alegría de los creyentes ante «el despojo» (ἁρπαγὴν) de sus posesiones, apuntando a una herencia eterna. El término abarca desde la incautación violenta hasta la avaricia interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63353, 'spa', 'Ser arrebatado en transporte divino', 'Ser arrebatado en transporte divino. Ser llevado o trasladado por el poder divino: transporte sobrenatural en lugar de violencia humana. Pablo relata haber sido arrebatado al tercer cielo y al paraiso (2 Co 12:2, 4), los creyentes seran arrebatados en las nubes en la venida del Senor (1 Ts 4:17), y el nino es arrebatado hacia Dios y su trono (Ap 12:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63354, 'spa', 'Arrebatar o apoderarse por la fuerza', 'Arrebatar o apoderarse por la fuerza. Apoderarse, arrebatar o tomar por la fuerza: el sentido central de apropiacion violenta y repentina. El lobo arrebata las ovejas (Jn 10:12), el maligno arrebata la palabra sembrada en el corazon (Mt 13:19), y nadie puede arrebatar a los creyentes de la mano del Padre (Jn 10:28-29). En Mt 11:12 el reino de los cielos sufre violencia y los violentos lo arrebatan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63355, 'spa', 'Saquear o llevarse bienes', 'Saquear o llevarse bienes. Saquear o llevarse posesiones de un lugar por la fuerza. En Mt 12:29, Jesus pregunta como puede alguien entrar en la casa del hombre fuerte y saquear sus bienes sin antes atarlo. Se trata de un sentido enfocado en la propiedad, distinto de la captura de personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63365, 'spa', 'Rapaz o ladrón', 'Rapaz, depredador o estafador; describe a quien se apodera de los bienes ajenos por violencia o fraude. En Mt 7:15 Jesús advierte sobre falsos profetas que son lobos «rapaces» (ἅρπαξ), el uso más vívidamente metafórico. Lc 18:11 sitúa a los ladrones en la oración autojustificante del fariseo. Las listas de vicios de Pablo en 1 Co 5:10-11 y 6:10 emparejan al ἅρπαξ con avaros e idólatras como personas excluidas del reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63366, 'spa', 'Arras, garantía espiritual', 'De uso exclusivamente paulino, describe al Espíritu Santo como garantía divina de la herencia futura. Segunda de Corintios 1:22 y 5:5 hablan de Dios dando «las arras» (ἀρραβῶνα) del Espíritu en nuestros corazones, señal que asegura la redención completa. Efesios 1:14 llama al Espíritu «la garantía» (ἀρραβὼν) de nuestra herencia hasta que la posesión de Dios sea redimida. El trasfondo comercial semítico enriquece la metáfora teológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63368, 'spa', 'Varón, masculino', 'Persona de sexo masculino o el sexo masculino en general, usado sustantivamente para indicar el sexo biológico en contraste con lo femenino (θῆλυς). Jesús cita Génesis 1:27 en Mt 19:4 y Mr 10:6 (''varón y hembra los creó'') para establecer la enseñanza sobre el matrimonio según el orden de la creación. Lucas 2:23 aplica la ley de consagración mosaica a todo varón primogénito. Romanos 1:27 usa el término para varones en relaciones del mismo sexo. Gálatas 3:28 proclama la igualdad en Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63372, 'spa', 'Enfermo o doliente', 'Físicamente enfermo o doliente, referido a una condición corporal de enfermedad o debilidad que requiere sanidad. Las cinco apariciones en el NT involucran dolencias físicas concretas: Jesús sanando a los enfermos (Mt 14:14; Mr 6:5, 13), una promesa sobre la imposición de manos sobre los enfermos (Mr 16:18) y la advertencia de Pablo sobre la debilidad por participar indignamente de la comunión (1 Co 11:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63373, 'spa', 'Práctica homosexual masculina', 'Ambas ocurrencias paulinas incrustan el término en catálogos de vicios graves. En 1 Corintios 6:9 sigue a ''afeminados'' (μαλακοί) en lo que puede ser un par refiriéndose a parejas pasivas y activas. En 1 Timoteo 1:10 aparece en una lista extraída del marco moral del Decálogo. Las traducciones modernas luchan con la precisión, como lo evidencian los glosarios multilingües usando terminología genérica de ''homosexuales''. El término técnico señala conducta específica dentro de categorías más amplias de inmoralidad sexual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63375, 'spa', 'Artemisa de Éfeso', 'La diosa griega Artemisa, específicamente en su manifestación efesia como deidad de la fertilidad y protectora de la ciudad, cuyo culto se centraba en el célebre templo de Éfeso. Las cinco apariciones se hallan en Hch 19:24–35, documentando la conmoción económica y religiosa provocada por el impacto del evangelio en su culto. Demetrio el platero moviliza a su gremio advirtiendo que la predicación monoteísta de Pablo amenaza su sustento y la honra de la diosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63377, 'spa', 'ahora, en este momento', 'ahora, en este momento');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63381, 'spa', 'pan, hogaza', 'Pan u hogaza: el alimento básico de grano del mundo antiguo, usado literalmente para el sustento diario y la provisión milagrosa (Mt 6:11; 14:17; 15:34), y figuradamente para el alimento espiritual y el signo eucarístico. La declaración de Jesús «Yo soy el pan de vida» (Jn 6:35) y la institución de la Última Cena («esto es mi cuerpo», Mt 26:26) confieren a ἄρτος un peso sacramental que trasciende su significado cotidiano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63385, 'spa', 'Sazonar', 'Usado tanto para la sal en sentido literal como para el habla en sentido metafórico. Marcos 9:50 y Lucas 14:34 preguntan cómo la sal que ha perdido su sabor podrá ser sazonada (ἀρτυθήσεται), señalando su imposibilidad retórica. Colosenses 4:6 ordena que el habla sea «sazonada» (ἠρτυμένος) con sal, es decir, llena de gracia y apta para cada interlocutor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63387, 'spa', 'Ángel de rango superior', 'Las dos ocurrencias neotestamentarias presentan al arcángel en contextos escatológicos y de guerra espiritual. En 1 Tesalonicenses, el grito del arcángel acompaña la parusía de Cristo. En Judas, Miguel el arcángel modela contención incluso al contender con Satanás, rehusando pronunciar juicio blasfemo. El término es universalmente transliterado a través de idiomas (español ''arcángel'', francés ''archange'', alemán ''Erzengel''), reflejando su estatus técnico como título celestial dentro de la angelología bíblica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63388, 'spa', 'Antiguo, viejo, desde el principio', 'Antiguo, viejo, desde el principio. Relativo a tiempos pasados o generaciones anteriores — antiguo, viejo. Jesús lo usa para referirse a los mandamientos de la Torá dados ''a los antiguos'' (Mt 5:21, 33), mientras las multitudes identifican a Jesús como posiblemente ''uno de los antiguos profetas'' que ha regresado (Lc 9:8, 19). Pedro y Jacobo apelan a ''los primeros días'' y a ''generaciones antiguas'' en el Concilio de Jerusalén (Hch 15:7, 21). A Mnasón se le describe como un ''discípulo antiguo'' (Hch 21:16), y Apocalipsis llama a Satanás ''la serpiente antigua'' (Ap 12:9; 20:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63394, 'spa', 'principio, comienzo', 'Sentido temporal primario (43 ocurrencias): el principio, comienzo u origen de algo. Abarca el origen creacional («en el principio», Jn 1:1-2; He 1:10), el inicio del ministerio de Jesús (Mr 1:1), el comienzo de los dolores de parto (Mt 24:8) y las referencias a «desde el principio» (ἀπ'' ἀρχῆς). El español «principio», el francés commencement y el alemán Anfang lo traducen consistentemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63395, 'spa', 'gobernante, principado', 'Sentido cósmico-jerárquico (7 ocurrencias): gobernantes sobrenaturales o políticos, frecuentemente en plural ἀρχαί designando poderes angélicos o demoníacos en el orden invisible. Las listas paulinas de «principados y potestades» (Ro 8:38; Ef 6:12; Col 1:16) hacen de este un término clave en la angelología neotestamentaria. El español distingue claramente «principados» o «gobernantes», mientras que Lucas 12:11 extiende el término a magistrados terrenales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63396, 'spa', 'dominio, autoridad', 'La esfera abstracta o el cargo de gobierno: dominio, autoridad o poder gubernamental como tal (5 ocurrencias). Se distingue del sentido 2 al enfocarse en la autoridad misma y no en los seres que la ostentan. En 1 Co 15:24 Cristo destruye todo «dominio» (ἀρχήν); en Judas 1:6 los ángeles abandonan su «dignidad» propia. El alemán Herrschaft y el español «autoridad» captan este matiz abstracto e institucional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63397, 'spa', 'esquina, extremo', 'Sentido espacial concreto (2 ocurrencias): la esquina o extremo de un objeto físico. En la visión de Pedro en la azotea (Hch 10:11; 11:5), un gran lienzo desciende sostenido por sus cuatro ἀρχαί — sus cuatro «puntas». El español «extremos» refleja este uso especializado, que deriva de la idea raíz de «punto de partida» aplicada a los bordes desde los cuales se extiende la tela.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63406, 'spa', 'Autor y pionero', 'Originador, fundador o pionero que a la vez inicia y guía — aplicado en el NT exclusivamente a Cristo en sus roles como fuente y campeón de la vida, la salvación y la fe. Hechos 3:15 lo llama ''Autor de la vida'', Hechos 5:31 lo designa ''Príncipe y Salvador'', Hebreos 2:10 lo presenta como ''pionero de la salvación'' perfeccionado por el sufrimiento, y Hebreos 12:2 como ''autor y consumador de la fe''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63408, 'spa', 'sumo sacerdote', 'El sacerdote principal o sumo sacerdote del sistema templario judío. En singular designa al titular del cargo que realizaba en exclusiva el ritual del Día de la Expiación (Caifás en Mt 26:57; Anás en Lc 3:2); en plural designa la aristocracia sacerdotal con autoridad religiosa y política en Jerusalén (Mt 2:4; 21:23). Hebreos reapropia el título para Cristo como sumo sacerdote eterno según el orden de Melquisedec (He 4:14–5:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63416, 'spa', 'Colaborador ministerial', 'Ambas referencias provienen de la correspondencia colosense. La exhortación en Colosenses 4:17 a ''completar'' o ''cumplir'' su ministerio sugiere que Arquipo enfrentaba desánimo o necesitaba recordatorio de responsabilidad. La designación de ''compañero de milicia'' en Filemón indica que Pablo lo veía como socio ministerial de primera línea, no mero adherente. Todos los testigos lingüísticos transliteran el nombre con variaciones fonéticas menores, reflejando su identidad como persona histórica en la red apostólica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63417, 'spa', 'Jefe de sinagoga', 'El oficial que presidía la sinagoga judía, responsable de organizar el culto, seleccionar lectores, mantener el orden y supervisar las instalaciones. La mayoría de las apariciones en el NT se centran en Jairo, el jefe de sinagoga que suplicó a Jesús que sanara a su hija moribunda (Mr 5:22, 35, 36, 38; Lc 8:49). Lucas 13:14 presenta a un jefe de sinagoga que se opone a la sanación en sábado, ilustrando la resistencia institucional ante Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63424, 'spa', 'Maestresala', 'Aparece exclusivamente en Juan 2:8-9 (tres veces) como el oficial que supervisaba el banquete de bodas en Caná. Los sirvientes llevaron el agua convertida en vino al «maestresala» (ἀρχιτρίκλινος), quien, sin saber su origen milagroso, lo probó y lo declaró excepcional. Su cargo como director del festín lo hacía el juez apropiado de la calidad del vino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63425, 'spa', 'comenzar, empezar', 'Comenzar o dar inicio a una acción, usado en voz media (ἄρχομαι) a lo largo del Nuevo Testamento con un complemento de infinitivo que especifica la actividad iniciada. Prominente en los Evangelios para marcar transiciones narrativas: Jesús «comenzó a predicar» (Mt 4:17), «comenzó a enseñar» (Mr 4:1), «comenzó a mostrar» el sufrimiento (Mt 16:21). El español «comenzó», el francés commencer y el alemán anfangen convergen en este sentido singular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63440, 'spa', 'Gobernar o dominar', 'Ambos pasajes abordan el gobernar sobre las naciones/gentiles pero con tonos contrastantes. En Marcos 10:42, Jesús critica cómo los gobernantes gentiles ''se enseñorean'' de los súbditos, usando esto como ejemplo negativo. En Romanos 15:12, el gobierno de Cristo sobre los gentiles es la esperanza profética. El rango semántico incluye gobierno legítimo y dominación opresiva; el contexto determina la valencia. Las glosas multilingües uniformemente usan términos de gobierno y autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63441, 'spa', 'gobernante, líder, jefe', 'gobernante, líder, jefe');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63451, 'spa', 'Especias aromáticas funerarias', 'Especias fragantes o sustancias aromáticas preparadas para ungir un cadáver, usadas exclusivamente en el NT en relación con la sepultura de Jesús y la visita de las mujeres a la tumba tras la resurrección. Marcos 16:1 registra la compra de ἀρώματα después del sábado, Lucas 23:56 su preparación antes del reposo, Lucas 24:1 su transporte al sepulcro al amanecer, y Juan 19:40 la generosa provisión de mirra y áloes por parte de Nicodemo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63452, 'spa', 'Variante textual genealógica', 'Ambas referencias en Mateo 1:7-8 ubican esta figura en la genealogía real entre Abías y Josafat, la posición ocupada por el rey Asa en la narrativa bíblica. La variante textual refleja cómo la transmisión manuscrita podía introducir nombres familiares en lugar de nombres menos comunes. La evidencia de traducción moderna (francés ''Asa'', alemán ''Asa'') muestra que la mayoría de traductores adoptan la lectura ''Asa'', tratando ''Asaf'' como error escribal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63453, 'spa', 'Firme e inamovible', 'Las dos ocurrencias demuestran aplicaciones literales (Hechos 27:41 - barco firmemente encallado) y metafóricas (Hebreos 12:28 - reino que no puede ser sacudido). Ambas enfatizan resistencia a fuerzas externas que intentan mover o desestabilizar. El pasaje de Hebreos contrasta este reino inconmovible con cosas creadas sacudibles siendo removidas. Todos los testigos lingüísticos usan construcciones de in-movible o in-sacudible, reflejando la morfología del griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63454, 'spa', 'Fuego inextinguible', 'Inextinguible, que no se puede apagar — describe un fuego que resiste todo intento de extinción, usado exclusivamente en el NT para el fuego del juicio divino. La imagen de la era en Juan el Bautista (Mateo 3:12; Lucas 3:17) y las advertencias de Jesús sobre la Gehena (Marcos 9:43, 45) emplean este adjetivo para transmitir la finalidad e inevitabilidad del castigo escatológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63455, 'spa', 'Impiedad, irreverencia', 'La cualidad o disposición de ser impío — irreverencia, falta de piedad o desprecio hacia Dios y sus normas. Este sustantivo abstracto no designa un pecado específico, sino una orientación fundamental alejada de Dios. Romanos 1:18 lo empareja con ἀδικία (injusticia) en el clásico doble encuadre de la rebelión humana: irreverencia hacia Dios e injusticia hacia los demás.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63460, 'spa', 'Impío, irreverente (persona)', 'Impío, irreverente (persona). Persona que carece de reverencia hacia Dios, viviendo en activo desprecio del orden divino — un individuo impío o irreverente. Usado sustantivamente para designar a aquellos a quienes Cristo justifica a pesar de su impiedad (Ro 4:5; 5:6), a los destruidos en el Diluvio por su irreverencia (2 P 2:5) y a quienes enfrentan condenación escatológica (1 Ti 1:9; Jud 4, 15). El énfasis recae en la oposición activa y consciente al orden divino, no en la simple debilidad moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63465, 'spa', 'Lascivia, sensualidad', 'Lascivia, sensualidad. Abandono moral excesivo y desvergonzado — lascivia, sensualidad o libertinaje que desafía abiertamente las normas sociales y divinas. Aparece en listas de vicios junto a la fornicación y la impureza (Mr 7:22; Gá 5:19; 2 Co 12:21), y caracteriza la conducta de falsos maestros que explotan la licencia moral (2 P 2:2, 18; Jud 4). El énfasis no recae meramente en el pecado en sí, sino en su carácter descarado y desenfrenado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63472, 'spa', 'Identificador tribal', 'Ambas ocurrencias del Nuevo Testamento usan Aser como identificador tribal en lugar de referirse al patriarca mismo. La afiliación tribal de Ana (Lucas 2:36) es una de las pocas identidades tribales específicas mencionadas en el Nuevo Testamento, mostrando preservación de memoria genealógica. El listado de Apocalipsis 7:6 incluye las doce tribus en completitud simbólica. Todos los idiomas transliteran el nombre con variaciones fonéticas menores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63473, 'spa', 'Debilidad, fragilidad o falta de fuerza en sentido abstracto, ya sea física, mor', 'Debilidad, fragilidad o falta de fuerza en sentido abstracto, ya sea física, moral, espiritual o circunstancial, sin señalar una condición médica específica. En español, ''debilidad'' traduce consistentemente este sentido. Pablo lo usa para la limitación humana (Ro 6:19, ''por la debilidad de vuestra carne'') y la intercesión del Espíritu por nuestra fragilidad (Ro 8:26). En 2 Corintios 12:9-10, la debilidad se convierte paradójicamente en el lugar donde se perfecciona el poder divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63475, 'spa', 'Enfermedad física, dolencia o padecimiento corporal concreto del cual se puede s', 'Enfermedad física, dolencia o padecimiento corporal concreto del cual se puede sufrir y ser sanado. En español, ''enfermedad'' y ''enfermedades'' distinguen consistentemente este sentido de la fragilidad abstracta. Mateo 8:17 cita a Isaías para describir a Jesús cargando con las enfermedades reales, y Juan 5:5 se refiere a un hombre que llevaba treinta y ocho años en su enfermedad. Juan 11:4 presenta la enfermedad de Lázaro como ocasión para la gloria de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63482, 'spa', 'estar enfermo, estar doliente', 'estar enfermo, estar doliente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63485, 'spa', 'ser débil, carecer de fuerza', 'ser débil, carecer de fuerza');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63502, 'spa', 'Debilidad general que abarca fragilidad moral, vulnerabilidad espiritual e insig', 'Debilidad general que abarca fragilidad moral, vulnerabilidad espiritual e insignificancia social. Las cartas de Pablo concentran la mayoría de los usos aquí, contrastando el poder divino con el humano (Ro 5:6; 1 Co 1:25-27). Las traducciones multilingües lo traducen consistentemente como ''débil'' sin connotación médica, apuntando a una deficiencia abstracta de fuerza o capacidad más que a enfermedad corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63504, 'spa', 'Enfermedad o dolencia física que requiere sanidad', 'Enfermedad o dolencia física que requiere sanidad. Aparece en pasajes de comisionamiento donde Jesús envía a los discípulos a sanar a los enfermos (Lc 9:2; 10:9) y en la escena del juicio mateano sobre visitar a los enfermos (Mt 25:43-44). En español se pasa a ''enfermo'' (persona enferma) y los contextos siempre involucran acción terapéutica, distinguiéndolo de la mera fragilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63510, 'spa', 'La provincia romana de Asia (Ἀσία), que abarcaba el occidente de Asia Menor con ', 'La provincia romana de Asia (Ἀσία), que abarcaba el occidente de Asia Menor con Éfeso como ciudad principal. Es la región del ministerio prolongado de Pablo (Hch 19:10, 26), sede de las siete iglesias de Apocalipsis (Ap 1:4) y lugar de origen de los peregrinos judíos en Pentecostés (Hch 2:9). El Espíritu inicialmente prohibió a Pablo entrar en Asia (Hch 16:6), lo que hace aún más significativa su posterior labor extendida allí. Judíos de Asia acusan a Pablo en Jerusalén (Hch 21:27; 24:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63520, 'spa', 'Odres', 'Odres. Recipiente de cuero hecho de piel de animal, usado para almacenar y transportar vino. Todas las apariciones en el NT pertenecen a la parabola de Jesus sobre el vino nuevo que requiere odres nuevos (Mt 9:17; Mr 2:22; Lc 5:37-38). Los odres viejos y endurecidos no resisten la presion del vino nuevo en fermentacion y revientan, por lo que se necesitan odres frescos. La imagen sirve como metafora de la incompatibilidad entre las realidades del nuevo pacto y las estructuras rigidas antiguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63525, 'spa', 'saludar, enviar saludos', 'Saludar a alguien o enviar saludos, especialmente en contextos epistolares. Este sentido abrumadoramente dominante (54 de 60 ocurrencias) llena las secciones finales de las cartas paulinas: «Saludad a Prisca y Aquila» (Ro 16:3), «Todos los santos os saludan» (2 Co 13:13). El español emplea consistentemente «saludad/saludaos». Jesús invoca esta convención social cuando prohíbe saludar a nadie por el camino (Lc 10:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63528, 'spa', 'recibir, abrazar', 'Dar la bienvenida o abrazar a alguien o algo con alegría, ya sea al llegar o desde la distancia. Hechos 21:7 y 21:19 describen a Pablo recibido calurosamente por los creyentes, mientras Hebreos 11:13 extiende la metáfora poderosamente: los patriarcas «saludaron» las promesas desde lejos, abrazándolas por fe sin poseerlas. El español transita hacia «habiendo saludado» o «saludándolos», enfatizando la recepción cumplida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63540, 'spa', 'despedirse, tomar licencia', 'Despedirse o tomar licencia de alguien al partir. Hechos 20:1 describe a Pablo abrazando a los discípulos y partiendo tras el tumulto de Éfeso, y Hechos 21:6 registra la conmovedora despedida en Tiro. El español lo traduce «despidiéndose» y «nos despedimos», una separación clara del vocabulario de saludo del sentido 1. El alemán usa igualmente verabschiedet («tomar licencia»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63546, 'spa', 'Saludo, salutación', 'Saludo, salutación. Expresión hablada o escrita de bienvenida, respeto o buenos deseos — una salutación intercambiada en un encuentro personal o añadida al final de una carta. Abarca el saludo proféticamente significativo de María a Elisabet (Lc 1:29, 41, 44), los saludos públicos en las plazas que Jesús criticó a los fariseos por buscar (Mt 23:7; Mr 12:38), y los cierres autógrafos epistolares de Pablo (1 Co 16:21; Col 4:18; 2 Ts 3:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63548, 'spa', 'Sin mancha, inmaculado', 'Sin mancha, inmaculado — moral o ritualmente puro, libre de toda contaminación. En 1 Pedro 1:19 el adjetivo describe a Cristo como cordero sacrificial sin defecto, enraizando la metáfora en los requisitos de pureza levíticos. Las demás apariciones (1 Timoteo 6:14; Santiago 1:27; 2 Pedro 3:14) aplican la misma imagen a la conducta moral de los creyentes, instándolos a mantenerse o mantener su confesión sin mácula.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63551, 'spa', 'Moneda de valor mínimo', 'Ambas ocurrencias evangélicas emplean el asarion en lógica proverbial idéntica: los gorriones cuestan muy poco en el mercado, sin embargo Dios conoce a cada uno. La versión de Lucas intensifica el punto: cinco gorriones por dos asaria muestra que los compradores obtienen un quinto gorrión ''gratis'', sin embargo ninguno es olvidado. El préstamo latino aparece a través de familias lingüísticas, con francés ''as'' y español ''ases'' adaptando el latín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63553, 'spa', 'Ciudad portuaria de Asia', 'Ambas referencias en Hechos (20:13-14) narran el mismo evento desde ángulos ligeramente diferentes: el plan de reunirse en Asos (v.13) y su cumplimiento (v.14). La decisión de Pablo de caminar mientras otros navegaban pudo haber sido por razones pastorales (visitar creyentes) o preferencia personal por el viaje terrestre. Todos los testigos lingüísticos transliteran el nombre de la ciudad uniformemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63555, 'spa', 'Belleza física excepcional', 'Ambas apariciones describen a Moisés como un bebé excepcionalmente hermoso (Hechos 7:20; Heb 11:23). Hechos usa la frase llamativa ''hermoso para Dios'' (ἀστεῖος τῷ θεῷ), sugiriendo aprobación divina más allá de la mera apariencia física. Esta belleza motivó a sus padres a medidas extraordinarias de protección. Los testigos multilingües traducen uniformemente con terminología de belleza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63556, 'spa', 'Cuerpo celeste luminoso visible en el cielo nocturno, que abarca tanto usos lite', 'Cuerpo celeste luminoso visible en el cielo nocturno, que abarca tanto usos literales como simbólicos en el Nuevo Testamento. Literalmente, la estrella que guió a los magos hasta el Mesías recién nacido (Mt 2:2, 7, 9-10), el oscurecimiento de las estrellas en portentos apocalípticos (Mt 24:29; Mc 13:25), y la analogía paulina de la diferente gloria estelar para el cuerpo de resurrección (1 Co 15:41). Simbólicamente dominante en Apocalipsis: siete estrellas en la mano derecha de Cristo representan a los ángeles de las siete iglesias (Ap 1:16, 20; 2:1; 3:1), una gran estrella llamada Ajenjo envenena las aguas (Ap 8:10-11), y Cristo mismo es ''la estrella resplandeciente de la mañana'' (Ap 22:16; cf. 2:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63561, 'spa', 'Inestabilidad espiritual', 'Ambas apariciones en 2 Pedro describen la misma categoría de personas: aquellos inestables en la fe que son vulnerables a distorsionar las cartas de Pablo y otras Escrituras (3:16) y que son seducidos por falsos maestros (2:14). El término sugiere no rebelión activa sino más bien falta de arraigo firme que hace a uno fácilmente influenciable. Los cuatro testigos lingüísticos usan terminología de ''inestable/inconstante''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63562, 'spa', 'Falta de afecto familiar', 'Ambos catálogos de vicios paulinos incluyen este término entre los colapsos morales de la sociedad. Romanos 1:31 lo coloca en una lista de características de quienes suprimen la verdad sobre Dios. 2 Timoteo 3:3 advierte a Timoteo sobre personas en los ''últimos días'' que exhiben esta insensibilidad. La ausencia de afecto natural representa degradación moral profunda: la disolución de vínculos humanos fundamentales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63563, 'spa', 'Desviarse doctrinalmente', 'Usado exclusivamente en las Epístolas Pastorales para describir desviación doctrinal y moral. En 1 Timoteo 1:6, algunos «erraron el blanco» (ἀστοχήσαντες) y se entregaron a palabrerías inútiles. En 1 Timoteo 6:21, algunos «se desviaron» (ἠστόχησαν) de la fe por ambicionar riquezas. En 2 Timoteo 2:18, dos personas «erraron» (ἠστόχησαν) respecto a la verdad al enseñar una resurrección ya cumplida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63564, 'spa', 'Relámpago', 'Relámpago: la descarga eléctrica visible en la atmósfera, empleada tanto en sentido literal como en vívidas imágenes apocalípticas. Jesús describe la venida del Hijo del Hombre como un relámpago que resplandece por todo el cielo (Mt 24:27; Lc 17:24), y vio a Satanás caer como un relámpago del cielo (Lc 10:18). Las escenas de la sala del trono en Apocalipsis presentan relámpagos repetidamente como señales del poder divino (Ap 4:5; 8:5; 11:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63566, 'spa', 'Resplandor, fulgor', 'Resplandor o fulgor brillante: una extensión metafórica que describe una luminosidad deslumbrante sin referencia a un relámpago real. En Lucas 11:36, cuando todo el cuerpo está lleno de luz, será enteramente luminoso ''como cuando la lámpara con su fulgor (ἀστραπή) te alumbra''. En español se traduce aquí como ''luz'' o ''resplandor'' en lugar de ''relámpago'', señalando un matiz semántico distinto al fenómeno atmosférico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63567, 'spa', 'Resplandor celestial', 'Ambas apariciones lucanas involucran brillo celestial. En Lucas 17:24, Jesús usa la visibilidad repentina del relámpago a través del cielo como metáfora de la naturaleza inconfundible de su venida. En Lucas 24:4, la vestimenta deslumbrante de los seres angelicales señala origen celestial. Los participios presentes en ambos pasajes enfatizan el destello/brillo continuo en lugar de un destello único.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63568, 'spa', 'Estrella o cuerpo celeste', 'Estrella o cuerpo celeste: un objeto luminoso en el cielo nocturno. Las cuatro apariciones neotestamentarias se refieren a estrellas literales en contextos variados: señales escatológicas cósmicas (Lucas 21:25), una imagen astral idolátrica (Hechos 7:43), referencia de navegación perdida en una tormenta (Hechos 27:20) y un símil de multitud innumerable tomado del pacto abrahámico (Hebreos 11:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63571, 'spa', 'Falto de entendimiento', 'Carente de comprensión o discernimiento moral, describe a quien no logra captar lo que debería ser evidente. En los Evangelios, Jesús llama ἀσύνετοι a los discípulos cuando no entienden su enseñanza sobre la contaminación (Mt 15:16; Mc 7:18). Pablo lo usa en Romanos para caracterizar la mente entenebrecida de los idólatras (Ro 1:21) y su insensibilidad moral (Ro 1:31), y cita a Moisés aplicándolo a una nación que provocará a Israel a celos (Ro 10:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63573, 'spa', 'Certeza y seguridad', 'Abarca tanto la certeza intelectual como la seguridad física. Lucas 1:4 indica que Lucas escribió para que Teófilo conociera «la certeza» (ἀσφάλειαν) de la instrucción evangélica: conocimiento firme y confiable. Hechos 5:23 describe que todo estaba «en seguridad» (ἀσφαλείᾳ), con puertas cerradas y guardias apostados, pero los presos habían desaparecido. En 1 Tesalonicenses 5:3, Pablo advierte contra la falsa confianza de quienes proclaman «paz y seguridad».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63574, 'spa', 'Seguro y confiable', 'Cierto, fiable y seguro, aplicado a información que es firme y verificable, o a una realidad espiritual inquebrantable. En el contexto forense de Hechos, los comandantes y gobernadores romanos buscan ''los hechos ciertos'' sobre Pablo (Hch 21:34; 22:30; 25:26), donde el término significa conocimiento establecido y confiable. En contexto epistolar, Pablo recomienda la repetición como consejo ''seguro'' (Fil 3:1), y Hebreos 6:19 lo aplica a la esperanza cristiana como ancla firme del alma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63575, 'spa', 'Asegurar o sujetar', 'Hacer seguro, sujetar firmemente o custodiar contra la fuga o la manipulación. En el relato del sellado del sepulcro (Mateo 27:64-66), el verbo aparece tres veces cuando las autoridades solicitan, reciben permiso y llevan a cabo el aseguramiento del lugar de sepultura de Jesús. En Hechos 16:24 describe al carcelero sujetando los pies de los prisioneros en el cepo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63576, 'spa', 'Segura y certeramente', 'Enfatiza la manera segura o cierta de una acción o conocimiento. Marcos 14:44 describe a Judas organizando la entrega de Jesús «con seguridad» (ἀσφαλῶς), lejos de las multitudes para minimizar resistencia. Hechos 2:36 presenta a Pedro declarando «con certeza» (ἀσφαλῶς) que Dios hizo a Jesús Señor y Mesías. Hechos 16:23 ordena custodiar «de forma segura» (ἀσφαλῶς) a Pablo y Silas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63577, 'spa', 'Actuar impropiamente', 'Las dos apariciones en Corintios abordan aplicaciones diferentes: posible impropiedad sexual en el compromiso (7:36) y estándar general para el comportamiento del amor (13:5). El primer pasaje es notoriamente difícil; Pablo puede estar dirigiéndose a un padre, a un hombre y su prometida, o al matrimonio espiritual. El segundo establece que el amor genuino observa límites y respeto apropiados. Las traducciones multilingües enfatizan la indecencia y el comportamiento inadecuado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63578, 'spa', 'Vergüenza e indecencia', 'Las dos apariciones abarcan el rango semántico: inmoralidad sexual (Rom 1:27) y exposición vergonzosa/desnudez (Apoc 16:15). Romanos enfatiza la desvergüenza de los actos mismos. Apocalipsis usa imágenes de vestimenta para vigilancia espiritual, donde la desnudez representa vergüenza no preparada. El trasfondo de la Septuaginta de este término como eufemismo para genitales informa ambos pasajes. La evidencia multilingüe muestra consistencia en vergüenza e indecencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63580, 'spa', 'Vida disoluta', 'Describe una vida desenfrenada y disoluta caracterizada por el exceso moral. Efesios 5:18 contrasta la embriaguez que conduce a la ἀσωτία con la plenitud del Espíritu. Tito 1:6 exige que los hijos de los ancianos no sean acusados de ἀσωτίας, es decir, disipación desenfrenada. Primera Pedro 4:4 describe a los antiguos compañeros paganos asombrados de que los creyentes ya no participen en el torrente de ἀσωτίας. La raíz sugiere algo «que no puede salvarse», indicando un derroche irrecuperable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63584, 'spa', 'Conducta desordenada', 'Ambos usos en 2 Tesalonicenses 3 abordan el mismo problema: creyentes que viven de manera desordenada al negarse a trabajar y entrometerse en asuntos ajenos (v.6, 11). La metáfora militar de estar ''fuera de filas'' encaja con la autodescripción de Pablo de trabajar día y noche como ejemplo. El francés preserva la forma griega directamente mientras otros idiomas usan terminología de desorden. El dominio de Relaciones captura cómo esto afecta la comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63585, 'spa', 'Sin descendencia', 'Aparece exclusivamente en Lucas 20:28-30 (tres veces) en el diálogo de Jesús con los saduceos sobre la resurrección. La ley de Moisés exigía que un hombre se casara con la viuda de su hermano que hubiese muerto ἄτεκνος para preservar la línea familiar. El escenario hipotético presenta siete hermanos, cada uno muriendo ἄτεκνος, resaltando el absurdo que los saduceos veían en la doctrina de la resurrección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63586, 'spa', 'mirar fijamente, clavar la vista — Dirigir la mirada con intensidad sostenida e ', 'mirar fijamente, clavar la vista — Dirigir la mirada con intensidad sostenida e intencional hacia una persona, objeto o visión celestial. Característico de Lucas-Hechos (12 de 14 apariciones en el NT), donde marca momentos decisivos: la congregación de Nazaret contemplando fijamente a Jesús (Lc 4:20), la criada escudriñando a Pedro (Lc 22:56), los apóstoles mirando fijamente al Señor que ascendía (Hch 1:10), Pedro y Juan clavando los ojos en el hombre paralítico (Hch 3:4), y Esteban contemplando la gloria de Dios antes de su martirio (Hch 7:55). No es una mirada casual sino una contemplación cargada de expectativa, reconocimiento o revelación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63592, 'spa', 'Sin o aparte de', 'Lucas emplea esta preposición algo arcaica dos veces en el capítulo 22. En el versículo 35, Jesús recuerda a los discípulos su misión previa sin provisiones, estableciendo precedente para dependencia de Dios y hospitalidad. En el versículo 6, describe la estrategia de Judas de traicionar a Jesús lejos de las multitudes que podrían haber intervenido. La mayoría de los idiomas modernos usan construcciones simples de ''sin'', con el alemán preservando más arcaísmo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63593, 'spa', 'Deshonrar, afrentar', 'Tratar con deshonra, desprecio o vergüenza; insultar o degradar. La evidencia multilingüe converge en un solo sentido: español ''deshonrar'', francés ''déshonorer'', alemán ''entehren'' — todos preservan la estructura privativa (quitar la honra). En Marcos 12:4 y Lucas 20:11 describe el trato dado a los siervos del dueño de la viña en la parábola de Jesús; en Juan 8:49 Jesús afirma que él no deshonra al Padre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63599, 'spa', 'Deshonra, vergüenza, desgracia', 'El estado de deshonra, vergüenza o desgracia: ser tenido en baja estima o sometido a indignidad. Abarca el desprecio social (Rom 9:21, el vaso hecho para ''uso deshonroso''), la degradación moral (Rom 1:26, ''pasiones vergonzosas'') y la humillación corporal (1 Cor 15:43, el cuerpo sembrado ''en deshonra''). Todas las lenguas principales lo traducen con un solo término que niega el honor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63603, 'spa', 'Sin honor o despreciado', 'Sin honor, deshonrado o despreciado: carente del reconocimiento o la estima debidos. Jesús aplica la palabra a un profeta rechazado en su tierra (Mateo 13:57; Marcos 6:4), mientras Pablo la usa para apóstoles tratados con desprecio (1 Corintios 4:10) y para miembros del cuerpo considerados menos honorables (1 Corintios 12:23). La forma comparativa muestra que el concepto admite grados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63604, 'spa', 'Vapor transitorio', 'Las dos apariciones ilustran aplicaciones diferentes: señales escatológicas (Hechos 2:19) y enseñanza sapiencial sobre la brevedad de la vida (Santiago 4:14). En Hechos, el vapor de humo es parte de la conmoción cósmica. En Santiago, el vapor sirve como metáfora para la naturaleza fugaz de la vida: visible momentáneamente y luego desaparecido. Ambos aprovechan la propiedad física del vapor como transitorio e insustancial. Los cuatro idiomas usan terminología de vapor/humo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63606, 'spa', 'Malo, impropio o perverso', 'Malo, perverso o impropio: moralmente o legalmente fuera de orden. La declaración del ladrón arrepentido de que Jesús no ha hecho «nada malo» (Lucas 23:41) y la solicitud de exponer cualquier cosa «impropia» en Pablo (Hechos 25:5) emplean el adjetivo en un registro judicial-moral. 2 Tesalonicenses 3:2 lo empareja con πονηρός («malvado») para describir opositores hostiles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63611, 'spa', 'arrogancia obstinada', 'Ambas apariciones describen personas en posiciones de influencia que afirman erróneamente su voluntad: líderes eclesiásticos descalificados (Tito 1:7) y falsos maestros (2 Pedro 2:10). El término captura lo opuesto a la humildad centrada en otros: estas personas operan desde una arrogancia egocéntrica. Pablo contrasta esto con el liderazgo de siervo requerido en la casa de Dios. Las glosas multilingües usan terminología de arrogante/obstinado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63612, 'spa', 'generosidad voluntaria', 'Ambas apariciones en 2 Corintios 8 elogian la generosidad voluntaria. En el versículo 3, los macedonios dieron más allá de su capacidad ''por propia voluntad'', sin presión de Pablo. En el versículo 17, Tito fue a Corinto ''por propia voluntad'', mostrando iniciativa. El término enfatiza la motivación interna y libertad que caracterizan el verdadero dar y servir cristianos. La evidencia interlingüística muestra terminología de ''por propia voluntad''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63614, 'spa', 'Tocar la flauta', 'Se usa en contextos de respuesta y comunicación. Mateo 11:17 y Lucas 7:32 recogen la queja de Jesús: «Ηὐλήσαμεν» (tocamos la flauta) pero no quisisteis bailar, metáfora del rechazo a la proclamación gozosa del evangelio. Primera Corintios 14:7 emplea αὐλούμενον para ilustrar que hasta los instrumentos musicales deben emitir notas claras para ser comprendidos, aplicándolo a la claridad de los dones espirituales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63615, 'spa', 'patio, atrio — Patio o atrio abierto perteneciente a un edificio grande, ya sea ', 'patio, atrio — Patio o atrio abierto perteneciente a un edificio grande, ya sea un palacio, una mansión o el complejo del templo. El αὐλή del sumo sacerdote es el ejemplo más destacado, escenario de las tres negaciones de Pedro la noche del arresto de Jesús (Mt 26:58, 69; Mc 14:54, 66; Lc 22:55; Jn 18:15). También aparece como el atrio del palacio de Caifás donde se reunió el concilio (Mt 26:3) y como el patio del pretorio del gobernador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63616, 'spa', 'redil, corral — Redil o corral cerrado para guardar ovejas, restringido al discu', 'redil, corral — Redil o corral cerrado para guardar ovejas, restringido al discurso del Buen Pastor de Jesús en Juan 10. En Jn 10:1, quien no entra ''por la puerta en el redil (αὐλή) de las ovejas'' es un ladrón, y en Jn 10:16 Jesús habla de ''otras ovejas que no son de este redil''. El español cambia decididamente a ''redil'' en vez de ''patio'', marcando un claro límite léxico entre el sentido arquitectónico y el pastoril.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63618, 'spa', 'músico de eventos públicos', 'Ambas referencias del Nuevo Testamento ubican a los flautistas en contextos de eventos públicos: duelo funerario (Mateo 9:23) y el cese de la vida urbana (Apocalipsis 18:22). Mateo específicamente nota el ruido y la multitud que acompañan a los dolientes profesionales con sus flautas. La profecía de Apocalipsis de músicos silenciados simboliza desolación completa. Todos los testimonios lingüísticos usan terminología de flautista, reconociendo el instrumento específico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63619, 'spa', 'alojamiento nocturno', 'Ambas apariciones en los Evangelios describen el patrón de alojamiento de Jesús durante la Semana de Pasión: quedándose en Betania (Mateo 21:17) o en el Monte de los Olivos (Lucas 21:37) mientras enseñaba diariamente en el templo de Jerusalén. El tiempo imperfecto en Mateo enfatiza acción habitual: Jesús repetidamente se alojaba allí. El patrón muestra que Jesús evitaba quedarse en la potencialmente hostil Jerusalén por la noche. Las glosas interlingüísticas uniformemente usan terminología de pasar la noche.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63621, 'spa', 'Crecimiento o aumento intransitivo', 'Crecimiento o aumento intransitivo: el sujeto mismo crece en tamaño, número, fuerza o influencia. Abarca plantas (Mt 6:28, los lirios; Mc 4:8, la semilla que da fruto), personas (Lc 1:80, Juan el Bautista; Lc 2:40, el niño Jesús) y la expansión de la palabra de Dios (Hch 6:7; 12:24; 19:20). En español, ''crece/crecen'' traducen esto con verbos intransitivos simples que reflejan un proceso orgánico sin agente externo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63628, 'spa', 'Causativo', 'Causativo: hacer crecer algo, conceder o producir aumento en otra entidad. El paradigma es 1 Co 3:6-7, donde Pablo, Apolos y Dios desempeñan roles distintos: plantar, regar y hacer crecer. 2 Co 9:10 extiende esto a Dios multiplicando la cosecha de justicia. En español, ''haciendo crecer'' (causar el crecimiento) se distingue claramente del simple ''crece,'' marcando la agencia divina como fuente del verdadero aumento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63635, 'spa', 'crecimiento del cuerpo', 'Ambas apariciones paulinas usan fraseo idéntico sobre el crecimiento del cuerpo (τὴν αὔξησιν τοῦ σώματος) en pasajes paralelos sobre Cristo como cabeza y la iglesia como cuerpo. Efesios 4:16 enfatiza la contribución de cada parte al crecimiento. Colosenses 2:19 subraya el crecimiento que viene de Dios. La metáfora biológica del crecimiento encaja con la imaginería del cuerpo de Pablo. El francés preserva el término griego directamente mientras otros idiomas usan terminología de crecimiento/aumento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63636, 'spa', 'mañana, el día siguiente — Adverbio temporal que designa el día inmediatamente p', 'mañana, el día siguiente — Adverbio temporal que designa el día inmediatamente posterior al momento presente o a un punto de referencia en la narración. En los Evangelios aparece de forma prominente en la enseñanza sapiencial de Jesús sobre la ansiedad y la futilidad de la presunción humana (Mt 6:30, 34; Lc 12:28; cf. Stg 4:14), donde ''mañana'' simboliza el futuro incontrolable. En contextos narrativos (Lc 10:35; Hch 23:15; 25:22), funciona simplemente como marcador temporal para el día siguiente, sin carga simbólica adicional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63638, 'spa', 'Severidad percibida', 'Ambas apariciones en Lucas 19 ocurren en el mismo diálogo parabólico: la acusación del siervo (v.21) y la respuesta del amo usando las propias palabras del siervo (v.22). El siervo afirma que el temor al amo severo excusa su inacción, pero el amo demuestra que esta misma lógica debería haber motivado depositar el dinero en el banco. El término caracteriza la severidad percibida en lugar de la real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63639, 'spa', 'Suficiencia divina', 'Las dos apariciones paulinas muestran matices diferentes. En 2 Corintios 9:8, ''suficiencia'' o ''todo lo que necesitan'' enfatiza que Dios suple recursos adecuados para la generosidad. En 1 Timoteo 6:6, ''contentamiento'' enfatiza la satisfacción con lo que uno tiene en lugar de anhelar más. Ambos contrastan con la autarkeia estoica autosuficiente al fundamentar la suficiencia en la provisión divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63642, 'spa', 'Acción sin intervención humana', 'Ambas apariciones neotestamentarias involucran procesos que suceden sin intervención humana: crecimiento de cultivos (Marcos 4:28) y apertura milagrosa de puertas (Hechos 12:10). La parábola de Marcos enfatiza la autonomía misteriosa del crecimiento: los agricultores plantan y cosechan pero no pueden controlar el proceso mismo del crecimiento. Hechos enfatiza la acción divina haciendo que la puerta se abra sola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63645, 'spa', 'pronombre de tercera persona', 'Uso anafórico básico: retoma un referente previamente mencionado en el discurso. ''Le dijo'', ''lo vio'', ''de él'', ''a ella''. Funciona en todos los casos oblicuos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63668, 'spa', 'intensivo o de identidad', 'Función enfática que subraya la identidad del sujeto o la acción directa del agente: ''él mismo'', ''ella en persona'', ''por sí mismo''. Sin artículo y a menudo en posición predicativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63700, 'spa', 'posesivo', 'En genitivo funciona como adjetivo posesivo de tercera persona: ''su (de él/ella)'', ''sus (de ellos/ellas)''. Más enfático que el simple artículo en función posesiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63705, 'spa', 'Aquí o allí', 'Adverbio deíctico de lugar que significa ''justo aquí'' o ''justo allí'', señalando la ubicación inmediata donde alguien se encuentra o debe permanecer. En Mt 26:36, Jesús instruye a los discípulos a sentarse αὐτοῦ mientras él se retira a orar; en Lc 9:27, marca el lugar exacto donde están las personas. Los pasajes de Hechos (15:34; 18:19; 21:4) lo emplean para indicar dónde se quedaron los viajeros durante las misiones apostólicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63706, 'spa', 'autorreferencia reflexiva — Verdadera autorreferencia reflexiva, donde el pronom', 'autorreferencia reflexiva — Verdadera autorreferencia reflexiva, donde el pronombre dirige la acción de vuelta hacia el sujeto gramatical. Esto cubre la gran mayoría de las apariciones: Jesús no se confía a sí mismo (Jn 2:24), Dios se glorifica a sí mismo (Jn 13:32), antiguos enemigos se hacen amigos ''entre sí'' (Lc 23:12). El español usa consistentemente ''a sí mismo/a'' para expresar este valor reflexivo genuino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63709, 'spa', 'pronombre simple de tercera persona — Pronombre de tercera persona no reflexivo,', 'pronombre simple de tercera persona — Pronombre de tercera persona no reflexivo, un desarrollo del koiné donde ἑαυτοῦ reemplaza al simple αὐτός sin significado verdaderamente reflexivo. En Mc 9:16 y Hch 10:21, el pronombre funciona como un simple ''él'' o ''ellos'' sin indicar acción autodirigida. Esta confusión entre pronombres reflexivos y personales está bien documentada en los papiros helenísticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63720, 'spa', 'Cortar o cercenar una parte del cuerpo, específicamente una oreja, mediante una ', 'Cortar o cercenar una parte del cuerpo, específicamente una oreja, mediante una acción física violenta con un arma. Las tres ocurrencias describen el mismo incidente de Getsemaní desde diferentes perspectivas evangélicas (Mt 26:51; Mr 14:47; Lc 22:50). El paso a la amputación física se refleja en ''cortó'' en lugar del abstracto ''quitar'', y el aoristo enfatiza un golpe único y decisivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63721, 'spa', 'Quitar, remover o retirar algo de su lugar o asociación — ya sea una deshonra (L', 'Quitar, remover o retirar algo de su lugar o asociación — ya sea una deshonra (Lc 1:25), una mayordomía (Lc 16:3), pecados (Ro 11:27; Heb 10:4), o palabras de un libro profético (Ap 22:19). La acción es abstracta o relacional: algo es levantado, revocado o anulado. El español emplea ''quitar'' para enfatizar la remoción más que la acción física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63729, 'spa', 'Desfigurar o destruir', 'Hacer invisible, volver irreconocible, destruir o causar que desaparezca, abarcando un espectro que va de la desfiguración a la desaparición total. Los hipócritas ''desfiguran'' sus rostros para exhibir su ayuno (Mt 6:16), mientras la polilla y el óxido ''destruyen'' los tesoros almacenados (Mt 6:19-20). En cita profética, a los burladores se les anuncia que ''perecerán'' (Hch 13:41), y Santiago compara la vida humana a un vapor que ''se desvanece'' (Stg 4:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63732, 'spa', 'Lugar de evacuación', 'Ambas apariciones están en la misma enseñanza sobre lo limpio e inmundo (Mateo 15:17; Marcos 7:19). Jesús traza el camino de la comida: boca → estómago → letrina, demostrando que la comida no entra al corazón y por tanto no puede contaminar moralmente. Marcos añade el comentario editorial de que Jesús así declaró limpios todos los alimentos. Los pasajes paralelos muestran que esta era enseñanza central sobre la fuente de la contaminación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63735, 'spa', 'La remisión o perdón de pecados — con diferencia el uso dominante en el NT (15 d', 'La remisión o perdón de pecados — con diferencia el uso dominante en el NT (15 de 17 ocurrencias). Aparece en la fórmula bautismal de Marcos 1:4 y Lucas 3:3, en las palabras de Jesús sobre la copa en la Última Cena (Mt 26:28) y en la predicación apostólica de Hechos. La imagen subyacente es la cancelación de una deuda: Dios ''suelta'' al pecador de la obligación contraída. El español ''perdón'' captura fielmente este sentido teológico central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63736, 'spa', 'Liberación física o social — la puesta en libertad de cautivos u oprimidos', 'Liberación física o social — la puesta en libertad de cautivos u oprimidos. Ambas ocurrencias provienen de Lucas 4:18, donde Jesús cita Isaías 61:1 en la sinagoga de Nazaret. El español se desdobla en ''liberación'' y ''libertad'', revelando la dimensión concreta y corporal: no se trata de un perdón metafórico sino de una auténtica puesta en libertad. El significado clásico de la palabra (dispensa, exención, descargo) aflora aquí y ancla el término en su trasfondo sociopolítico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63738, 'spa', 'Conexiones corporales', 'Ambas apariciones están en contextos casi idénticos sobre el cuerpo siendo sostenido y unido a través de cada ligamento de soporte (Efesios 4:16; Colosenses 2:19). La metáfora de Pablo enfatiza que la unidad y crecimiento de la iglesia dependen de conexiones apropiadas: cada miembro funcionando en relación con otros. La forma genitiva plural sugiere múltiples puntos de conexión a través del cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63739, 'spa', 'Incorrupción, inmortalidad', 'La cualidad de ser imperecedero o inmortal: ausencia de corrupción física y de muerte. Pablo contrasta el cuerpo corruptible sembrado en la sepultura con el cuerpo incorruptible resucitado en gloria (1 Co 15:42, 50, 53-54). En Romanos 2:7 designa lo que los justos persiguen, y en 2 Timoteo 1:10 es lo que la manifestación de Cristo ha iluminado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63742, 'spa', 'Integridad, pureza moral', 'Solidez moral, integridad o pureza de carácter: una extensión ética de la idea raíz de incorrupción. Se usa una vez en Tito 2:7 para describir la cualidad que debe distinguir la sana enseñanza. En español se traduce aquí como ''integridad'' en lugar de ''incorrupción'', señalando que los traductores perciben un matiz ético distinto del sentido de inmortalidad física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63743, 'spa', 'Imperecedero, incorruptible', 'No sujeto a corrupción, deterioro ni muerte: imperecedero e inmortal. Cuando se aplica a Dios, subraya la trascendencia divina más allá de toda deterioración material (Ro 1:23; 1 Ti 1:17). Cuando se aplica al cuerpo de resurrección, marca la transformación de lo mortal a lo inmortal (1 Co 15:52). Aplicado a recompensas y herencia, contrasta lo transitorio terrenal con la permanencia celestial (1 Co 9:25; 1 P 1:4, 23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63748, 'spa', 'dejar, abandonar', 'Dejar o abandonar físicamente: partir de un lugar, desamparar a una persona o dejar algo atrás. Los discípulos de Jesús dejan sus redes (Mt 4:20), la fiebre deja a la suegra de Pedro (Mt 8:15) y el hombre deja padre y madre (Mt 19:5). El árabe taraka, el coreano 버리다/떠나다 y el suajili -acha convergen en este sentido concreto de partida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63750, 'spa', 'ser dejado, ser abandonado', 'Pasivo de dejar: ser dejado atrás, ser abandonado, quedar desolado. El lamento de Jesús sobre Jerusalén — ''vuestra casa os es dejada desierta'' (Mt 23:38) — y el apocalíptico ''uno será tomado y el otro dejado'' (Mt 24:40–41) portan sobretones de juicio. El árabe yutraku (pasivo) y el coreano 버려지다 vierten este sentido con precisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63751, 'spa', 'ser perdonado (pasivo)', 'Voz pasiva: los pecados o las deudas ''son perdonados'' — el pasivo divino (passivum divinum) donde Dios es el agente implícito. La declaración de Jesús ''tus pecados te son perdonados'' (Mt 9:2; Mc 2:5; Lc 7:48) desata controversia sobre la autoridad divina. El árabe ghufira (pasivo), el coreano 사함받다 y el suajili -samehewa marcan gramaticalmente esta construcción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63753, 'spa', 'perdonar, cancelar (activo)', 'Perdón activo de pecados o cancelación de deudas — el corazón teológico de ἀφίημι. El Padrenuestro (Mt 6:12) y la parábola del siervo que no perdona (Mt 18:27, 32) hacen del perdón una ética central del reino. El árabe ghafara y el coreano 용서하다 distinguen consistentemente este sentido del de ''dejar'', evidenciando campos semánticos separados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63754, 'spa', 'permitir, dejar hacer', 'Permitir, dejar o consentir que alguien actúe — un sentido volitivo distinto de la partida física. Jesús dice a Juan ''permítelo ahora'' en su bautismo (Mt 3:15) e instruye a los discípulos a ''dejar'' que los niños se acerquen (Mt 19:14). El árabe samaha/da''a, el coreano 허락하다 y el hindi anumatī denā delimitan este campo semántico diferenciado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63761, 'spa', 'repudiar, divorciarse', 'Un sentido especializado en 1 Corintios 7:11–13 que significa ''repudiar, despedir'' al cónyuge — la disolución legal de un matrimonio. El español despida y el contexto jurídico grecorromano de ἀφίημι para el divorcio distinguen este sentido del simple abandono. Pablo aborda matrimonios mixtos donde uno de los cónyuges se ha convertido a la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63774, 'spa', 'soltar, entregar', 'Soltar o entregar, como cuando Jesús entrega su espíritu al morir (Mt 27:50). El árabe aslama (''rendirse, entregar''), el coreano 놓았다 y el suajili -toa (''dar, emitir'') convergen en un acto deliberado de liberación más que en un fallecer pasivo. Marcos 15:37 emplea el mismo verbo en paralelo, subrayando la agencia de Jesús en su momento final.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63782, 'spa', 'descuidar, desatender', 'Descuidar o dejar sin cumplir deberes importantes — una omisión culpable, no una partida física. Jesús reprende a los fariseos por descuidar (ἀφίημι) la justicia, la misericordia y la fidelidad mientras diezman hierbas meticulosamente (Mt 23:23). El español descuidar y el hindi chhoḍnā en el sentido de abandonar la responsabilidad captan el peso moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63815, 'spa', 'libre de avaricia', 'La palabra aparece exclusivamente en instrucción ética sobre cualidades de carácter, tanto en la lista de calificaciones para supervisores en 1 Timoteo como en el llamado al contentamiento en Hebreos. Las traducciones en español, francés y alemán preservan la estructura compuesta negativa, mostrando cómo esta virtud fue entendida en diversas culturas como libertad activa de la codicia en lugar de mera ausencia de riqueza. Las dos ocurrencias enmarcan esta virtud como fundamental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63817, 'spa', 'Apartarse, retirarse o abandonar un lugar, persona o situación en sentido litera', 'Apartarse, retirarse o abandonar un lugar, persona o situación en sentido literal y físico. Once ocurrencias cubren la separación espacial: Ana ''no se apartaba del templo'' (Lc 2:37), el diablo ''se apartó de él hasta un momento oportuno'' (Lc 4:13), Jesús ordena a los malvados ''apartaos de mí'' (Lc 13:27), y las cadenas de Pedro ''cayeron de sus manos'' cuando el ángel lo sacó (Hch 12:10). El español ''apartarse'' y ''retirarse'' expresan con claridad este movimiento de separación física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63818, 'spa', 'Arrastrar, desviar o provocar que otros se rebelen — un uso transitivo causativo', 'Arrastrar, desviar o provocar que otros se rebelen — un uso transitivo causativo donde el sujeto conduce a personas lejos de su lealtad. Una única ocurrencia clara en Hechos 5:37 registra que Judas el Galileo ''hizo apartarse al pueblo tras de sí'' en una insurrección fallida durante el censo. El español ''hizo apartarse'' y el francés ''entraîna'' confirman la fuerza causativa: no se trata de una partida propia sino de la seducción activa de otros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63821, 'spa', 'Abandonar la fe, apostatar — una extensión metafórica y teológica donde la parti', 'Abandonar la fe, apostatar — una extensión metafórica y teológica donde la partida es espiritual y no espacial. Tres pasajes de gran peso portan este sentido: los oyentes de terreno pedregoso que ''en el tiempo de la prueba se apartan'' (Lc 8:13), la advertencia profética de que ''en los últimos tiempos algunos apostatarán de la fe'' (1 Ti 4:1), y la exhortación a cuidar ''que no haya en ninguno de vosotros corazón malo de incredulidad para apartarse del Dios vivo'' (He 3:12). El español distingue entre ''apartarse'' y ''apostatar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63831, 'spa', 'Intervención repentina', 'Señala intervenciones divinas súbitas o acontecimientos dramáticos inesperados. Hechos 2:2 describe el Pentecostés: ἄφνω vino el sonido de un viento recio del cielo. Hechos 16:26 narra el terremoto de medianoche: ἄφνω se sacudieron los cimientos y se abrieron las puertas. Hechos 28:6 relata cómo los malteses, tras esperar en vano que Pablo muriera por la víbora, cambiaron ἄφνω de parecer. El término enfatiza la inmediatez divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63832, 'spa', 'Sin temor, con valentía', 'Con intrépida confianza: servir o hablar sin estar paralizado por el miedo. El himno de Zacarías contempla adoración «sin temor» (Lucas 1:74); Pablo desea que Timoteo trabaje «sin temor» (1 Corintios 16:10); y los filipenses proclaman el evangelio «intrépidamente» (Filipenses 1:14). Transmite santa audacia fundada en la confianza en Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63834, 'spa', 'fijar la mirada', 'Ambas ocurrencias bíblicas involucran atención deliberada dirigida hacia un foco específico. Filipenses 2:23 usa la forma participial en la expectativa de Pablo de ''ver'' cómo resultan las cosas, mientras que la famosa exhortación de Hebreos 12:2 de mirar ''a Jesús'' captura el significado esencial de la palabra de fijar la mirada apartándola de distracciones competitivas. El francés ''regarder'' y el alemán ''hinschauen'' reflejan esta focalización intencional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63835, 'spa', 'Apartar o consagrar a alguien para un llamado sagrado o misión divina, con Dios ', 'Apartar o consagrar a alguien para un llamado sagrado o misión divina, con Dios como agente último de la elección. El Espíritu Santo ordena: ''Apartadme a Bernabé y a Saulo'' (Hch 13:2), y Pablo se describe como ''apartado para el evangelio'' desde su nacimiento (Ro 1:1; Gá 1:15, evocando Jeremías 1:5). El español ''apartado'' transmite la idea de ser señalado dentro de un grupo mayor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63836, 'spa', 'Separarse socialmente, retirarse de la asociación con un grupo', 'Separarse socialmente, retirarse de la asociación con un grupo. Pablo cita a Isaías: ''Salid de en medio de ellos, y apartaos'' (2 Co 6:17), instando a los creyentes a mantener la santidad distanciándose de asociaciones impuras. En Gálatas 2:12, Pedro ''se apartaba'' de los creyentes gentiles cuando llegaron hombres de parte de Jacobo, una retirada social motivada por el temor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63838, 'spa', 'Separar o clasificar a las personas en grupos en el juicio escatológico, con los', 'Separar o clasificar a las personas en grupos en el juicio escatológico, con los ángeles o el Hijo del Hombre como agente. En Mateo 25:32 el rey-pastor separa las naciones como un pastor divide ovejas de cabras, y en Mateo 13:49 los ángeles separan a los malvados de entre los justos al fin del siglo. Hechos 19:9 extiende esto a Pablo separando a los discípulos de la sinagoga.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63842, 'spa', 'Excluir o marginar de una comunidad, funcionando como una forma de castigo o per', 'Excluir o marginar de una comunidad, funcionando como una forma de castigo o persecución social. En Lucas 6:22 Jesús pronuncia una bienaventuranza sobre aquellos a quienes otros ''aparten'', vituperen y desechen por causa del Hijo del Hombre. Este sentido conlleva la connotación más fuerte de rechazo comunitario y expulsión formal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63845, 'spa', 'Ocasión, oportunidad', 'Una ocasión, oportunidad o asidero: un punto de partida que posibilita o provoca una acción ulterior. En Rom 7:8 y 7:11, el pecado toma el mandamiento como su base operativa (semejante al sentido militar clásico de un punto de partida). En 2 Cor 5:12 y 11:12, Pablo habla de dar o negar a otros una ''ocasión'' para jactarse o calumniar. Los equivalentes multilingües confirman esta noción de oportunidad desencadenante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63846, 'spa', 'espumar violentamente', 'Ambos usos en Marcos 9:18 y 9:20 describen el mismo síntoma del muchacho poseído durante convulsiones demoníacas. La forma participial presente enfatiza la naturaleza continua y repetida del espumar, que sirvió como señal visible del poder del espíritu sobre el niño. Las traducciones multilingües mantienen consistentemente la naturaleza visceral y física de esta producción de espuma, mostrando cómo los traductores a través de las culturas reconocieron este fenómeno físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63848, 'spa', 'Insensatez culpable', 'Insensatez, necedad: una carencia culpable de entendimiento o buen juicio. Marcos 7:22 la sitúa en la lista de vicios de Jesús entre los males que contaminan a la persona desde dentro, junto a faltas morales como la maldad y el engaño. No es mera ignorancia, sino una ausencia voluntaria de sabiduría que conduce al pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63849, 'spa', 'Insensato o necio en sentido moral-espiritual — carente del discernimiento que p', 'Insensato o necio en sentido moral-espiritual — carente del discernimiento que proviene de temer a Dios. El veredicto de Dios sobre el rico necio que acumula posesiones descuidando su alma (Lc 12:20) es el uso paradigmático. Jesús lo aplica a los fariseos ciegos a la pureza interior (Lc 11:40). Pablo lo emplea con ironía retórica en su ''discurso del necio'' (2 Co 11:16, 19; 12:6, 11), desafía a los que dudan de la resurrección (1 Co 15:36), y Romanos 2:20 lo usa irónicamente para quienes se creen maestros de otros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63858, 'spa', 'Mudo, sin voz', 'Mudo, sin voz: que carece de la facultad o capacidad del habla. Hechos 8:32 aplica el adjetivo al Siervo Sufriente que no abre su boca, y 2 Pedro 2:16 describe a la burra de Balaam como animal ''sin voz'' que milagrosamente habló. Primera Corintios 12:2 caracteriza a los ídolos paganos como ''mudos'', incapaces de hablar por no estar vivos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63859, 'spa', 'rey infiel de Judá', 'Ambas ocurrencias en Mateo 1:9 sirven la función genealógica de conectar a Jotam con Ezequías a través de Acaz. A pesar de la notoria infidelidad de Acaz registrada en 2 Reyes 16 y 2 Crónicas 28, Mateo lo incluye en la línea mesiánica, demostrando que los propósitos de Dios trascienden el fracaso humano. La evidencia multilingüe muestra variación mínima (español ''Acaz'', francés ''Achaz'', alemán ''Ahas''), con todas las traducciones reconociendo su papel genealógico crucial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63860, 'spa', 'Nombre geográfico propio de la provincia senatorial romana que comprendía el sur', 'Nombre geográfico propio de la provincia senatorial romana que comprendía el sur de Grecia, con Corinto como su capital administrativa. Mencionada en relación con la comparecencia de Pablo ante Galión (Hch 18:12), la familia de Estéfanas como primicias de Acaya (1 Co 16:15), y la colecta para Jerusalén organizada junto con Macedonia (Ro 15:26; 2 Co 9:2). Consistentemente emparejada con Macedonia para referirse al conjunto de la iglesia griega.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63866, 'spa', 'sin gratitud', 'Lucas 6:35 usa la forma plural para describir una clase de personas que reciben bondad divina a pesar de su ingratitud, mientras que 2 Timoteo 3:2 lo incluye en una lista de vicios que caracterizan los difíciles últimos días. La evidencia multilingüe (español ''ingratos'', francés ''ingrat'', alemán preservando las formas griegas) confirma esto como una categoría moral reconocida a través de las culturas. Ambos contextos tratan la ingratitud como un defecto moral serio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63867, 'spa', 'Ancestro de Jesús', 'Mateo 1:14 contiene ambas menciones, vinculando a Aquim entre Azor y Eliud en el segmento final de la genealogía de Jesús. A pesar de nuestra falta de información histórica sobre este individuo, su inclusión demuestra la cuidadosa preservación que Mateo hace de la línea davídica a través de los siglos silenciosos entre el Antiguo y el Nuevo Testamento. La traducción consistente entre idiomas muestra que los traductores tratan este nombre como propio de una persona histórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63868, 'spa', 'Obra divina', 'Contrasta la construcción humana con la realidad divina o espiritual. Marcos 14:58 recoge el testimonio (falso) sobre Jesús destruyendo el templo «hecho con manos» y edificando uno ἀχειροποίητον, lo espiritual frente a lo físico. Segunda Corintios 5:1 contrasta la tienda terrenal con la morada celestial ἀχειροποίητον procedente de Dios. Colosenses 2:11 describe la circuncisión ἀχειροποίητον como el despojamiento espiritual de la naturaleza carnal en Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63869, 'spa', 'Niebla cegadora', 'Hechos 13:11 describe la ceguera judicial inmediata que cayó sobre Elimas como ''niebla y oscuridad'', usando el fenómeno físico literal para representar juicio espiritual. 2 Pedro 2:17 lo emplea metafóricamente, comparando a los falsos maestros con fuentes sin agua y ''nieblas impulsadas por la tormenta''—de apariencia impresionante pero en última instancia vacías e inestables. El español ''niebla/nieblas'', el francés ''brouillard'' y el alemán capturan este fenómeno de oscurecimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63870, 'spa', 'Inútil o improductivo', 'Mateo 25:30 lo aplica al siervo condenado cuyo fracaso en invertir los recursos de su amo lo hizo ''inútil'' y digno de castigo. Lucas 17:10 lo usa de manera sorprendentemente diferente: incluso los siervos obedientes deben llamarse ''inútiles'' porque solo han hecho lo requerido. El español ''inútil/inútiles'' y el francés ''inutile'' capturan la inutilidad práctica, mientras que el término griego subraya la falta de valor o servicio prestado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63873, 'spa', 'hasta, hasta que', 'Preposición (con genitivo) y conjunción que marca el punto final temporal («hasta que») o la extensión espacial («hasta») de una acción, estado o condición. En uso temporal, rige límites clave de la historia de la salvación: el silencio de Zacarías «hasta» el nacimiento de Juan (Lc 1:20), la línea temporal de la ascensión «hasta el día en que fue llevado arriba» (Hch 1:2), y marcadores escatológicos paulinos como «hasta que haya entrado la plenitud de los gentiles» (Ro 11:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63876, 'spa', 'Paja o tamo', 'Mateo 3:12 y Lucas 3:17 preservan la advertencia idéntica de Juan el Bautista sobre el que viene, quien separará el trigo de la paja. El español ''paja'', el francés ''paille'' y el alemán ''Ächuron'' todos se refieren a este producto de desecho agrícola. La paja representa a aquellos que resultan sin valor bajo el escrutinio divino—no apartados temporalmente sino destruidos permanentemente. El poder de la imagen radica en su inevitabilidad: el juicio separará de manera definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63878, 'spa', 'Ajenjo o amargura', 'Apocalipsis 8:11 menciona el ajenjo dos veces: primero como el nombre de la estrella que cae (''el nombre de la estrella se llama Ajenjo'') y luego describiendo las aguas amargas (''la tercera parte de las aguas se convirtió en ajenjo''). El español ''Ajenjo/ajenjo'' (mayúscula para el nombre propio), el francés y el alemán ''Wermut'' preservan esta función dual. La repetición enfatiza cómo la naturaleza misma de la estrella es la amargura, transformando todo lo que toca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63881, 'spa', 'Babilonia (ciudad/imperio) — La ciudad e imperio de Babilonia a orillas del Éufr', 'Babilonia (ciudad/imperio) — La ciudad e imperio de Babilonia a orillas del Éufrates, usada tanto como referencia histórica como designación profético-simbólica. Históricamente marca el exilio en la genealogía de Mateo (Mt 1:11-12, 17) y en el discurso de Esteban (Hch 7:43). Simbólicamente — casi con certeza refiriéndose a Roma — domina el Apocalipsis como la gran ciudad ramera destinada al juicio divino (Ap 14:8; 16:19; 17:5; 18:2, 10, 21). En 1 Pe 5:13, ''la que está en Babilonia'' es probablemente también una referencia críptica a Roma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63885, 'spa', 'Profundidad, lugar profundo', 'Profundidad o lugar profundo, usado para referirse a la profundidad física (suelo poco profundo en Mt 13:5, Mc 4:5; las aguas profundas en Lc 5:4) y a la profundidad metafórica (las riquezas insondables de la sabiduría de Dios en Ro 11:33; la dimensión cósmica que no puede separar del amor divino en Ro 8:39). En Efesios 3:18, Pablo ora para que los creyentes comprendan la anchura, longitud, altura y profundidad del amor de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63890, 'spa', 'Físicamente profundo', 'Que se extiende muy abajo desde la superficie. La samaritana observa que el pozo de Jacob es ''profundo'' (Juan 4:11), explicando por qué Jesús necesitaría un recipiente para sacar agua. Es el sentido más concreto y fundamental, reflejado en las lenguas: ''profundo'' en español, ''profond'' en francés. La hondura espacial sirve de base para toda extensión metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63892, 'spa', 'Profeta falso codicioso', 'Balaam sirve como ejemplo negativo en todo el NT. Segunda de Pedro 2:15 menciona a Βαλαάμ, hijo de Beor, que amó el salario de la injusticia. Judas 11 condena a quienes siguen su error por ganancia. Apocalipsis 2:14 advierte contra su enseñanza que indujo a Israel a la idolatría e inmoralidad. La transliteración se mantiene uniforme en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63894, 'spa', 'Bolsa para dinero', 'Bolsa de cuero o monedero para llevar dinero, usado en el comercio cotidiano. Las cuatro apariciones neotestamentarias se hallan en los escritos de Lucas, donde Jesús lo emplea tanto como artículo literal de viaje (Lucas 10:4; 22:35-36) como metáfora de una inversión celestial imperecedera (Lucas 12:33). Las glosas multilingües —''bolsa'' en español, ''bourse'' en francés— apuntan consistentemente a un monedero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63895, 'spa', 'arrojar, lanzar', 'Lanzar, arrojar o tirar activamente con fuerza física. El sentido más amplio y frecuente, que abarca piedras arrojadas, redes echadas al mar (Mt 4:18), perlas echadas ante los cerdos (Mt 7:6) y el dramático ''échate abajo'' de la tentación (Mt 4:6). El español arrojó/echó, el árabe طَرَحَ/أَلْقَى y el suajili kutupa captan la propulsión vigorosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63897, 'spa', 'ser arrojado, ser echado', 'Voz pasiva: ser arrojado, lanzado o echado, típicamente a un lugar de destrucción o confinamiento. Domina el lenguaje del juicio: todo árbol que no da buen fruto ''es echado al fuego'' (Mt 3:10), el siervo inútil ''es echado a las tinieblas de afuera'' (Mt 25:30) y la bestia ''fue arrojada al lago de fuego'' (Ap 19:20). El español es echado/fue arrojado refleja esta construcción pasiva de condena.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63899, 'spa', 'poner, depositar', 'Poner, colocar o depositar sin fuerza violenta — un registro semántico más suave. La viuda deposita sus monedas en el arca (Mc 12:41–44), el vino nuevo se echa en odres nuevos (Mt 9:17) y el dinero se deposita ante los banqueros (Mt 25:27). El español meter/depositar y el árabe وَضَعَ (colocar) distinguen este sentido del lanzamiento violento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63914, 'spa', 'yacer enfermo, estar postrado', 'Perfecto o pluscuamperfecto pasivo que describe un estado resultante de estar acostado, típicamente por enfermedad. El siervo del centurión ''yace'' paralítico en casa (Mt 8:6), la suegra de Pedro ''estaba acostada'' con fiebre (Mt 8:14) y Lázaro ''estaba echado'' a la puerta del rico (Lc 16:20). El español echado/estaba echado y el árabe مَطْرُوح confirman el sentido estativo-resultativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63931, 'spa', 'azotar, golpear contra', 'Referido a fuerzas naturales que golpean o azotan algo. Una sola aparición en Hechos 27:14, donde un viento violento (Εὐρακύλων) ''se lanzó contra'' la nave. El español se lanzó y el árabe هَاجَتْ (arreció/golpeó) captan la violencia meteorológica. Este sentido periférico preserva el uso griego más arcaico de βάλλω como fuerza impersonal que impacta un objetivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63938, 'spa', 'derramar, verter', 'Verter o derramar un líquido sobre algo o dentro de algo. María derrama ungüento sobre el cuerpo de Jesús para su sepultura (Mt 26:12) y Jesús echa agua en un lebrillo para lavar los pies (Jn 13:5). Aunque solo aparece dos veces, representa una extensión semántica genuina de proyectiles sólidos a corrientes líquidas, unificada por la idea de transferencia dirigida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63952, 'spa', 'ser bautizado, recibir bautismo', 'Ser bautizado o recibir el bautismo: uso en voz pasiva/media con 49 ocurrencias. Designa someterse al rito de inmersión en agua como señal de arrepentimiento (Mt 3:6; Mr 1:5), identificación con la muerte y resurrección de Cristo (Ro 6:3-4), o ingreso en la comunidad creyente (Hch 2:41; 8:12-13). El español «ser bautizados» marca este sentido receptivo con claridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63953, 'spa', 'bautizar, administrar bautismo', 'Bautizar o administrar el bautismo: uso en voz activa con 30 ocurrencias, donde el sujeto realiza el rito sobre otro. Juan declara «yo os bautizo en agua» (Mt 3:11; Mr 1:8); Jesús ordena a los discípulos «bautizad en el nombre del Padre, del Hijo y del Espíritu Santo» (Mt 28:19). El español «bauticé» (yo bauticé) y el alemán taufen (activo) reflejan la agencia del que administra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63972, 'spa', 'lavar, sumergir ritualmente', 'Lavar o sumergir en un contexto de purificación ritual ajeno al bautismo cristiano o joánico, atestiguado solo dos veces. En Marcos 7:4 los fariseos «lavan» (bautizan) copas, jarros y vasijas de bronce; en Lucas 11:38 un fariseo se asombra de que Jesús no se «lavó» antes de comer. Los traductores al español pasan de «bautizar» a «lavarse/sumergirse», reconociendo el marco ritual no sacramental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63984, 'spa', 'El rito o acto del bautismo', 'El rito o acto del bautismo: la inmersion en agua como ceremonia religiosa. En los Evangelios designa tanto el bautismo preparatorio de arrepentimiento de Juan (Mt 3:7; Mr 1:4; Hch 1:22) como el ''bautismo'' metaforico de sufrimiento que Jesus anticipaba (Mt 20:22-23; Mr 10:38-39). En las Epistolas significa la identificacion del creyente con la muerte, sepultura y resurreccion de Cristo (Ro 6:4; Ef 4:5; Col 2:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63985, 'spa', 'Lavamiento o bautismo', 'Lavamiento, inmersión o bautismo, que abarca tanto los ritos de purificación ceremonial judía como el bautismo sacramental cristiano. Marcos 7:4, 8 y Hebreos 9:10 emplean el término para la tradición farisaica y levítica de lavamientos rituales (de manos, vasijas y cuerpos), mientras que Colosenses 2:12 y Hebreos 6:2 lo aplican al bautismo cristiano como elemento fundacional de la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63986, 'spa', 'Bautista — Título sustantivado que significa ''el que bautiza'', usado exclusivame', 'Bautista — Título sustantivado que significa ''el que bautiza'', usado exclusivamente como epíteto de Juan hijo de Zacarías. Aparece en introducciones narrativas (Mt 3:1; Mc 6:25; Lc 7:20), en el testimonio de Jesús sobre la grandeza de Juan (Mt 11:11-12; Lc 7:28), y en la identificación temerosa de Herodes del hombre que había decapitado (Mt 14:2, 8; Mc 6:24-25). La forma articular ὁ βαπτιστής funciona como un cuasi-apellido que distingue a este Juan de otros personajes homónimos, particularmente del apóstol.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63988, 'spa', 'Mojar, sumergir, teñir', 'Mojar o introducir un objeto en un líquido para humedecer, teñir o con propósito simbólico. Los usos neotestamentarios van desde lo cotidiano (mojar pan, Lucas 16:24; Juan 13:26) hasta lo apocalíptico (un manto teñido en sangre, Ap 19:13). El español distingue ''mojar'' de ''teñir'', reflejando el rango del griego clásico donde βάπτω cubría el temple de metales y el tintado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63989, 'spa', 'Barrabás, el prisionero retenido por Roma por insurrección y homicidio, a quien ', 'Barrabás, el prisionero retenido por Roma por insurrección y homicidio, a quien Pilato ofreció como alternativa a Jesús en la amnistía pascual (Mt 27:16-26; Mr 15:7-15; Lc 23:18-25; Jn 18:40). La elección de la multitud de liberar a Barrabás y crucificar a Jesús constituye un momento crucial en las cuatro narrativas de la Pasión. Su nombre arameo, bar-Abba (''hijo del padre''), crea un llamativo paralelo irónico con Jesús, el verdadero Hijo del Padre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63992, 'spa', 'Extranjero, no grecohablante', 'Persona que no habla griego: un extranjero o ajeno cultural desde la perspectiva grecorromana. El término no conllevaba juicio moral inherente en la antigüedad; era ante todo una clasificación lingüística. En Hch 28:2 y 28:4, los malteses son βάρβαροι porque hablaban un dialecto púnico, aunque Lucas elogia su ''extraordinaria amabilidad''. El merismo de Pablo ''griegos y bárbaros, sabios e insensatos'' (Rom 1:14) abarca a toda la humanidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63996, 'spa', 'Agobiar, cargar', 'Agobiar, cargar o presionar pesadamente sobre alguien, casi siempre en voz pasiva en el NT, describiendo la experiencia de ser oprimido por el sueño (Mt 26:43; Lc 9:32), la disipación (Lc 21:34), el sufrimiento (2 Cor 1:8) o la mortalidad misma (2 Cor 5:4). El verbo transmite no solo peso sino la sensación vivida de ser abrumado o presionado más allá de la propia capacidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64001, 'spa', 'Oír con torpeza', 'Ambos pasajes citan el mismo texto profético sobre corazones endurecidos: ''sus oídos son torpes de oír'' (literalmente ''oyen pesadamente''). Mateo registra a Jesús aplicando las palabras de Isaías para explicar por qué habla en parábolas, mientras Hechos muestra a Pablo citando el mismo pasaje cuando algunos judíos rechazan el evangelio. El español ''pesadamente'' captura este sentido de peso y dificultad perceptiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64002, 'spa', 'Apóstol Bartolomé', 'Nombre propio que designa a uno de los doce apóstoles de Jesús, derivado del arameo bar-Talmay (''hijo de Tolmai''). Aparece exclusivamente en los catálogos apostólicos (Matt 10:3; Mark 3:18; Luke 6:14; Acts 1:13), siempre emparejado cerca de Felipe, lo cual refuerza la identificación tradicional con Natanael.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64005, 'spa', 'El nombre personal de Jose el levita de Chipre, llamado Bernabe (''hijo de consol', 'El nombre personal de Jose el levita de Chipre, llamado Bernabe (''hijo de consolacion'') por los apostoles. Figura clave en la expansion de la iglesia primitiva: modelo de generosidad radical (Hch 4:36-37), defensor de Saulo ante una iglesia de Jerusalen esceptica (Hch 9:27), pastor de la congregacion gentil en Antioquia (Hch 11:22-26) y colider del primer viaje misionero (Hch 13-14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64008, 'spa', 'Carga, peso', 'Una carga, peso o gravamen, ya sea trabajo físico, obligación moral o pesadez metafórica. En el NT la palabra abarca diversos registros: el peso opresivo del trabajo diario (Mt 20:12), la carga de requisitos religiosos (Hch 15:28), el ''eterno peso de gloria'' que paradójicamente supera la aflicción (2 Cor 4:17), el sobrellevar mutuamente las cargas en comunidad (Gál 6:2) y la autoridad apostólica (1 Tes 2:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64013, 'spa', 'Sobrenombre patronímico', 'Hechos 1:23 presenta a José Barsabás, un discípulo fiel que había acompañado a Jesús durante todo su ministerio y estaba calificado para ser apóstol. Hechos 15:22 presenta a Judas Barsabás, descrito como ''varón principal entre los hermanos'' encargado de entregar la crucial decisión del concilio de Jerusalén. Las formas españolas preservan el nombre arameo transliterado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64015, 'spa', 'Pesado, gravoso, severo', 'Pesado, gravoso, de peso o severo, abarcando peso físico, exigencias opresivas, importancia moral e intensidad feroz. Jesús lo emplea para las cargas «pesadas» impuestas por los fariseos (Mt 23:4) y para los asuntos «más importantes» de la Torá (Mt 23:23), donde el sentido literal de pesadez se convierte en metáfora de prioridad moral. Pablo lo aplica al «peso» percibido de sus cartas (2 Co 10:10), y Lucas lo usa para describir lobos «feroces» (Hch 20:29) y acusaciones «graves» (Hch 25:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64020, 'spa', 'atormentar, torturar — Atormentar, torturar o causar sufrimiento intenso — ya se', 'atormentar, torturar — Atormentar, torturar o causar sufrimiento intenso — ya sea físico, espiritual o escatológico. Este es el sentido dominante en once de las doce apariciones. Abarca encuentros demoníacos donde los espíritus malignos temen el juicio prematuro (Mt 8:29; Mc 5:7; Lc 8:28), el paralítico ''gravemente atormentado'' por la enfermedad (Mt 8:6), el alma justa de Lot atormentada por la iniquidad de Sodoma (2 Pe 2:8), y las visiones escatológicas del Apocalipsis con fuego y azufre (Ap 9:5; 14:10; 20:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64025, 'spa', 'azotar, sacudir por las olas — Azotar, sacudir o zarandear por fuerzas naturales', 'azotar, sacudir por las olas — Azotar, sacudir o zarandear por fuerzas naturales — específicamente de una barca golpeada por el viento y las olas. La única aparición en Mt 14:24 describe la embarcación de los discípulos ''siendo azotada'' (βασανιζόμενον) por las olas, siendo el viento contrario. El español traduce ''siendo azotada'', captando el castigo físico de los elementos en lugar del tormento personal. Este sentido preserva el matiz original más físico del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64032, 'spa', 'Tormento, angustia divina', 'Angustia o tortura severa, especialmente como castigo divino. En Apocalipsis el término se usa exclusivamente para el tormento escatológico: las langostas demoníacas infligen dolor como picadura de escorpión durante cinco meses (Ap 9:5), los adoradores de la bestia enfrentan tormento sin fin cuyo humo asciende por los siglos (Ap 14:11), y Babilonia recibe tormento proporcional a su autoglorificación (Ap 18:7, 10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64034, 'spa', 'Sufrimiento intenso', 'Describe sufrimiento severo, tanto físico como escatológico. Mateo 4:24 menciona a quienes padecían βασάνοις, enfermedades graves sanadas por Jesús. Lucas 16:23 y 16:28 emplean el término dos veces en la parábola del rico y Lázaro: el rico sufre en βασάνῳ, suplicando alivio y advirtiendo a sus hermanos. El trasfondo clásico de prueba mediante tortura enriquece la metáfora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64035, 'spa', 'reino, reinado, dominio', 'El gobierno soberano, la autoridad real o el dominio de un rey, junto con el ámbito o territorio sobre el cual esa autoridad se extiende. Con 163 apariciones, βασιλεία aparece abrumadoramente en la frase ''reino de Dios'' o ''reino de los cielos'' (Mt 3:2; 5:3; 6:33), abarcando tanto la irrupción presente del reinado de Dios por medio de Jesús como su consumación futura. La evidencia interlingüística — español ''reino'', francés ''royaume'', alemán ''Reich'' — confirma un núcleo semántico unívoco de soberanía real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64038, 'spa', 'Real, de la realeza', 'Lucas 7:25 usa la forma neutra plural para ''palacios reales'' donde viven personas espléndidamente vestidas, contrastando marcadamente con la vestimenta silvestre de Juan el Bautista. 1 Pedro 2:9 aplica el adjetivo a ''sacerdocio'', creando la poderosa frase ''sacerdocio real'' que eleva el estatus de los creyentes ante Dios. El español ''palacios/real'' muestra el rango desde literal a metafórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64039, 'spa', 'rey, soberano', 'Un monarca o gobernante supremo que ejerce autoridad real sobre un pueblo o territorio. Abarca a reyes terrenales como David (Mt 1:6), Herodes (Mt 2:1) y soberanos extranjeros, así como a Dios y a Cristo como Rey último. Las traducciones en todas las lenguas emplean consistentemente equivalentes reales directos (español ''rey'', francés ''roi''), subrayando el núcleo semántico inequívoco de gobierno soberano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64046, 'spa', 'Reinar o gobernar como rey, ejerciendo autoridad real y dominio soberano', 'Reinar o gobernar como rey, ejerciendo autoridad real y dominio soberano. Abarca desde el gobierno politico terrenal (Mt 2:22, Arquelao en Judea; Lc 19:14, 27, la parabola del noble) hasta lo cosmico y escatologico: la muerte reina a traves de Adan (Ro 5:14, 17), la gracia reina por medio de la justicia (Ro 5:21), y los creyentes reinaran con Cristo (Ap 20:4, 6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64056, 'spa', 'Uso participial sustantivado que designa a quienes reinan', 'Uso participial sustantivado que designa a quienes reinan: ''reyes'' o ''los que ejercen poder real.'' En 1 Timoteo 6:15, Dios es descrito como ''Rey de los que reinan'' (βασιλεὺς τῶν βασιλευόντων), donde el participio funciona como sustantivo denotando gobernantes soberanos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64057, 'spa', 'Real o regio', 'Real o regio: describe personas, posesiones o cualidades que pertenecen a un rey. El ''oficial real'' (βασιλικός) en Juan 4:46, 49 es un cortesano de Herodes Antipas; Hechos 12:20-21 lo usa para el territorio y vestimenta de Herodes Agripa. Santiago 2:8 lo aplica a la ''ley real'' del amor al prójimo, invistiendo el mandamiento con autoridad soberana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64058, 'spa', 'Soberana o reina', 'Mujer que ejerce autoridad real, ya sea como soberana reinante o consorte. El NT emplea el término para reinas históricas (la reina de Sabá, Matt 12:42; Luke 11:31; Candace de Etiopía, Acts 8:27) y metafóricamente para la arrogante autoentronización de Babilonia (Rev 18:7). La traducción constante como ''reina'' en español confirma su sentido real femenino directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64061, 'spa', 'Sobrellevar o soportar figuradamente dificultades, cargas y consecuencias', 'Sobrellevar o soportar figuradamente dificultades, cargas y consecuencias. Pablo insta a los fuertes a ''sobrellevar las flaquezas de los debiles'' (Ro 15:1), y Jesus dice a sus discipulos que aun no pueden ''soportar'' ciertas verdades (Jn 16:12). Galatas 5:10 advierte que el perturbador ''llevara su juicio.'' La metafora conserva el peso del transporte fisico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64062, 'spa', 'Cargar o transportar fisicamente objetos o personas', 'Cargar o transportar fisicamente objetos o personas. Es el uso mas frecuente: levantar piedras para arrojar (contexto de Jn 10:31), llevar un cantaro de agua por Jerusalen (Mr 14:13), o cargar a alguien en una camilla (Lc 7:14). Mateo 8:17 cita a Isaias para decir que Cristo ''cargo'' con nuestras enfermedades, donde la imagen fisica fundamenta la afirmacion teologica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64069, 'spa', 'Llevar marcas, senales o estigmas en el propio cuerpo', 'Llevar marcas, senales o estigmas en el propio cuerpo. En Galatas 6:17, Pablo declara ''yo llevo en mi cuerpo las marcas del Senor Jesus,'' cicatrices de persecucion que funcionan como marca de pertenencia y lealtad. Este uso singular transforma el verbo de transportar una carga externa a exhibir una identidad encarnada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64073, 'spa', 'Llevarse algo con connotacion de hurto o sustraccion no autorizada', 'Llevarse algo con connotacion de hurto o sustraccion no autorizada. Juan 12:6 especifica que Judas ''sustraia'' de la bolsa del dinero, pues era ladron. En Juan 20:15, Maria Magdalena teme que alguien se haya ''llevado'' el cuerpo del Senor. El sentido neutro de cargar se tine de sospecha y robo, con el contexto aportando la coloracion moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64084, 'spa', 'Zarza o zarzal', 'Arbusto espinoso o zarzal (género Rubus), especialmente la zarza ardiente de la teofanía del Éxodo. En Marcos 12:26 y Lucas 20:37, Jesús cita el pasaje de ''la zarza'' (Éxodo 3) para argumentar la resurrección; Hechos 7:30, 35 relata el encuentro de Moisés con el ángel en la llama. Lucas 6:44 lo emplea en un proverbio sobre recoger higos de espinos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64088, 'spa', 'Abominación, cosa detestable', 'Algo absolutamente detestable a los ojos de Dios, en especial objetos idolátricos, profanaciones sacrílegas o profunda corrupción moral. El término porta una fuerte carga cúltica heredada de la Septuaginta, donde traduce el hebreo toevah y shiqquts. Jesús lo aplica escatológicamente en la «abominación desoladora» presente en el lugar santo (Mt 24:15; Mr 13:14), en eco de la profecía de Daniel. Lucas 16:15 extiende su alcance a todo lo que los hombres exaltan pero Dios aborrece.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64092, 'spa', 'Aborrecer, detestar', 'Romanos 2:22 usa el participio presente medio en la pregunta retórica de Pablo: ''Tú que aborreces los ídolos, ¿cometes sacrilegio?'' La ironía es aguda: reclamar detestar el culto pagano mientras se actúa de maneras igualmente ofensivas a Dios. Apocalipsis 21:8 lista ''los abominables'' (participio pasivo perfecto) entre los condenados, refiriéndose a aquellos que se han vuelto detestables mediante idolatría y pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64093, 'spa', 'Firme, seguro, estable', 'Firme, seguro, estable, constante: lo que es confiable, sólido y que no puede fallar. Se aplica a la promesa abrahámica (Ro 4:16, hecha ''segura'' para toda la descendencia), la ley angélica (He 2:2, ''firme'' en sentido de vinculante legalmente), la confesión y esperanza del creyente (He 3:6, 14), el ancla del alma (He 6:19), la palabra profética (2 P 1:19) y el llamamiento y la elección (2 P 1:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64096, 'spa', 'Confirmar, establecer (activo)', 'Confirmar, establecer o validar en sentido activo: el agente hace firme una palabra, promesa o posición. En Marcos 16:20 el Señor confirma la palabra predicada mediante señales; en Romanos 15:8 Cristo confirma las promesas dadas a los padres. Véase también 1 Corintios 1:8 y 2 Corintios 1:21, donde Dios es quien confirma a los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64099, 'spa', 'Ser confirmado (pasivo)', 'Ser confirmado, establecido o afianzado en sentido pasivo o medio: el sujeto recibe o experimenta la acción confirmadora. En Colosenses 2:7 los creyentes son descritos como establecidos en la fe, y en Hebreos 2:3 la salvación anunciada primero por el Señor ''fue confirmada'' a los oyentes por quienes la escucharon de él directamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64104, 'spa', 'Confirmación, ratificación', 'Filipenses 1:7 vincula ''confirmación'' (bebaiōsis) directamente con la defensa y establecimiento del evangelio, con los creyentes compartiendo en la obra de Pablo de hacer el mensaje del evangelio firme y seguro. Hebreos 6:16 describe cómo un juramento funciona para proveer ''confirmación'' final, resolviendo toda disputa mediante garantía divina. El español ''confirmación'' preserva este sentido legal y de certeza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64105, 'spa', 'Profano o irreverente', 'Profano o irreverente: describe personas, discursos o conductas fuera de lo sagrado que tratan las cosas santas con desprecio. El NT lo usa para personas inicuas e impías (1 Tim 1:9), mitos inútiles y palabrerías irreverentes (1 Tim 4:7; 6:20; 2 Tim 2:16), y a Esaú como paradigma del hombre profano que vendió su primogenitura (Heb 12:16).');